<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use DateTime;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Notification\Message\Application\Usecase\Retrieve\MessageRetrieveUsecase;
use Civi\Lughauth\Features\Notification\Message\Application\Usecase\Retrieve\MessageRetrieveResult;

class MessageRetrieveController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly MessageRetrieveUsecase $retrieveUsecase,
    ) {
    }
    #[OA\Get(
        path: "/api/template/template{uid}",
        tags: ["Message"],
        description:"Create",
        parameters: [
               new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
          ],
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/MessageApiDTO")),
              new OA\Response(response: 404, description: "Not found"),
          ]
    )]
    public function retrieve(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Retrieve Message");
        $span = $this->startSpan("Retrieve Message");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $result = $this->retrieveUsecase->retrieve($uid);
            $value = $this->mapMessage($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapMessage(ServerRequestInterface $request, MessageRetrieveResult $value): MessageApiDTO
    {
        $this->logDebug("Map entity to output dto for Message");
        $span = $this->startSpan("Map entity to output dto for Message");
        try {
            $tenant = $value->getTenant();
            $dto = new MessageApiDTO();
            $dto->uid = $value->getUid();
            $dto->target = $value->getTarget();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->urgent = $value->isUrgent();
            $dto->content = $value->getContent();
            $dto->retries = $value->getRetries();
            $dto->createdAt = $value->getCreatedAt()?->format(DateTime::ATOM);
            $dto->sendAt = $value->getSendAt()?->format(DateTime::ATOM);
            $dto->lockAt = $value->getLockAt()?->format(DateTime::ATOM);
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
